class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        adj = [[i - 1, i + 1] for i in range(n + 1)]
        adj[1] = [2]
        adj[n] = [n - 1]
        if x != y:
            adj[x].append(y)
            adj[y].append(x)
        ans = [0] * n
        for src in range(1, n + 1):
            dist = [-1] * (n + 1)
            dist[src] = 0
            q = [src]
            for u in q:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        ans[dist[v] - 1] += 1
                        q.append(v)
        return ans

