class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        if x == y:
            return [2 * (n - d) for d in range(1, n)] + [0]
        mn, mx = min(x, y), max(x, y)
        diff = [0] * (n + 3)
        def add(l, r, w):
            if l <= r:
                diff[l] += w
                diff[r + 1] -= w
        a, b, L, g = mn - 1, n - mx, mx - mn + 1, mx - mn - 1
        t = (mn + mx + 1) // 2
        for d in range(1, a):
            add(d, d, 2 * (a - d))
        for d in range(1, b):
            add(d, d, 2 * (b - d))
        for d in range(1, L // 2 + 1):
            add(d, d, 2 * L if 2 * d < L else L)
        for i in range(1, mn):
            add(mn - i, t - i, 2)
            add(mn - i + 1, mn - i + mx - t, 2)
            add(mn + 2 - i, n - i - g, 2)
        for i in range(t, mx + 1):
            add(mx + 1 - i, n - i, 2)
        for i in range(mn, t):
            add(i - mn + 2, i - mn + n - mx + 1, 2)
        ans = []
        cur = 0
        for d in range(1, n + 1):
            cur += diff[d]
            ans.append(cur)
        return ans

