class Solution {
public:
    vector<int> countOfPairs(int n, int x, int y) {
        if (x == y) {
            vector<int> r(n, 0);
            for (int d = 1; d < n; d++) r[d-1] = 2 * (n - d);
            return r;
        }
        int mn = min(x, y), mx = max(x, y);
        vector<long long> diff(n + 3, 0);
        auto add = [&](int l, int r, long long w) {
            if (l <= r) { diff[l] += w; diff[r + 1] -= w; }
        };
        int a = mn - 1, b = n - mx, L = mx - mn + 1, g = mx - mn - 1;
        int t = (mn + mx + 1) / 2;
        for (int d = 1; d < a; d++) add(d, d, 2LL * (a - d));
        for (int d = 1; d < b; d++) add(d, d, 2LL * (b - d));
        for (int d = 1; d <= L / 2; d++) add(d, d, 2 * d < L ? 2LL * L : (long long)L);
        for (int i = 1; i < mn; i++) {
            add(mn - i, t - i, 2);
            add(mn - i + 1, mn - i + mx - t, 2);
            add(mn + 2 - i, n - i - g, 2);
        }
        for (int i = t; i <= mx; i++) add(mx + 1 - i, n - i, 2);
        for (int i = mn; i < t; i++) add(i - mn + 2, i - mn + n - mx + 1, 2);
        vector<int> r;
        long long cur = 0;
        for (int d = 1; d <= n; d++) { cur += diff[d]; r.push_back((int)cur); }
        return r;
    }
};

