class Solution {
    public int[] countOfPairs(int n, int x, int y) {
        if (x == y) {
            int[] r = new int[n];
            for (int d = 1; d < n; d++) r[d-1] = 2 * (n - d);
            return r;
        }
        int mn = Math.min(x, y), mx = Math.max(x, y);
        long[] diff = new long[n + 3];
        int a = mn - 1, b = n - mx, L = mx - mn + 1, g = mx - mn - 1;
        int t = (mn + mx + 1) / 2;
        for (int d = 1; d < a; d++) { diff[d] += 2L * (a - d); diff[d+1] -= 2L * (a - d); }
        for (int d = 1; d < b; d++) { diff[d] += 2L * (b - d); diff[d+1] -= 2L * (b - d); }
        for (int d = 1; d <= L / 2; d++) {
            long w = (2 * d < L) ? 2L * L : L;
            diff[d] += w; diff[d+1] -= w;
        }
        for (int i = 1; i < mn; i++) {
            diff[mn - i] += 2; diff[t - i + 1] -= 2;
            diff[mn - i + 1] += 2; diff[mn - i + mx - t + 1] -= 2;
            diff[mn + 2 - i] += 2; diff[n - i - g + 1] -= 2;
        }
        for (int i = t; i <= mx; i++) {
            diff[mx + 1 - i] += 2; diff[n - i + 1] -= 2;
        }
        for (int i = mn; i < t; i++) {
            diff[i - mn + 2] += 2; diff[i - mn + n - mx + 2] -= 2;
        }
        int[] r = new int[n];
        long cur = 0;
        for (int d = 1; d <= n; d++) { cur += diff[d]; r[d-1] = (int) cur; }
        return r;
    }
}

